<?php
require __DIR__.'/app.php';require_roles(['owner','company_manager','branch_manager']);$shopId=(int)$_SESSION['shop_id'];if(current_role()==='branch_manager'){$statisticsStatement=db()->prepare('SELECT COUNT(DISTINCT p.id) n,COALESCE(SUM(x.quantity),0) units FROM products p LEFT JOIN exports x ON x.product_id=p.id AND x.shop_id=p.shop_id AND x.branch_id=? WHERE p.shop_id=?');$statisticsStatement->execute([(int)$_SESSION['branch_id'],$shopId]);}else{$statisticsStatement=db()->prepare('SELECT COUNT(DISTINCT p.id) n,COALESCE(SUM(x.quantity),0) units FROM products p LEFT JOIN exports x ON x.product_id=p.id AND x.shop_id=p.shop_id WHERE p.shop_id=?');$statisticsStatement->execute([$shopId]);}$statistics=$statisticsStatement->fetch();page_start('الإحصاءات');echo '<section class="stats"><article class="card">عدد الأصناف<strong>'.e($statistics['n']).'</strong></article><article class="card">إجمالي الكمية الموزعة<strong>'.e($statistics['units']).'</strong></article></section>';page_end();

